const item = $input.first().json;

// extracted by HTML node
const texts = item.a_text || [];
const hrefs = item.a_href || [];

// state comes from the Merge node (because HTML node drops it)
const state = $node["Merge1"].json;

const prev = Array.isArray(state.allLinks) ? state.allLinks : [];
const newLinks = [];

for (let i = 0; i < Math.min(texts.length, hrefs.length); i++) {
  const t = String(texts[i] ?? '').trim();
  if (t === "Tovább..." || (t.startsWith("Tov") && t.endsWith("bb..."))) {
    const href = hrefs[i];
    if (href) newLinks.push(href);
  }
}

let hasNext = false;
for (const t of texts) {
  if (String(t ?? '').trim().includes("vetkez")) { // Következő
    hasNext = true;
    break;
  }
}

return [{
  json: {
    rootUrl: state.rootUrl,
    page: (state.page ?? 1) + 1,
    allLinks: [...prev, ...newLinks],
    hasNext,
    addedThisPage: newLinks.length,
  },
}];

let links = $input.first().json.allLinks;

// normalize to real JS array
if (typeof links === 'string') {
  try {
    links = JSON.parse(links);
  } catch {
    links = [];
  }
}

if (!Array.isArray(links)) {
  links = [];
}

console.log('links normalized:', links);

return links.map(url => ({
  json: { "url":url.href }
}));

const decodeNumericEntities = (s) =>
  s.replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));

const decodeBasicEntities = (s) =>
  s.replace(/&nbsp;/g, ' ')
   .replace(/&amp;/g, '&')
   .replace(/&quot;/g, '"')
   .replace(/&lt;/g, '<')
   .replace(/&gt;/g, '>');

const normalizePoem = (poemHtml) => {
  if (!poemHtml) return '';

  return decodeNumericEntities(
    decodeBasicEntities(
      String(poemHtml)
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/?span[^>]*>/gi, '')
        .replace(/<\/?p[^>]*>/gi, '')
        .replace(/\r\n/g, '\n')
    )
  ).trim();
};

return items.map((item) => {
  const title = (item.json.title || '').trim();
  const poemHtml = item.json.poem_html || item.json.poem_text_raw || '';
  const poem = normalizePoem(poemHtml);

  return {
    json: {
      url: item.json.url,
      title,
      poem,
    }
  };
});

const data = $input.first().json;
const agg = $node["Aggregate poems1"].json;

const poems = data.body.poems || [];
const chapters = data.body.chapters || [];

const BOOK_TITLE = data.bookTitle || agg.bookTitle || "Versek";
const BOOK_AUTHOR = data.bookAuthor || agg.bookAuthor || "Kiszely Jószefné";
const coverImageBase64 = data.body?.coverImage || data.coverImage;
const COVER_IMG_URL = coverImageBase64
  ? `data:image/png;base64,${coverImageBase64}`
  : (data.coverImgUrl || agg.coverImgUrl || "https://html.kiszely.work/assets/cover_pencil.jpg");

const escapeHtml = (s = "") =>
  String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

const slugify = (s = "") =>
  String(s)
    .toLowerCase()
    .trim()
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/g, "");

// Ensure unique ids even if titles repeat
const makeUniqueId = (() => {
  const used = new Map();
  return (base) => {
    const b = slugify(base) || "x";
    const n = (used.get(b) || 0) + 1;
    used.set(b, n);
    return n === 1 ? b : `${b}-${n}`;
  };
})();

const IMPRINT_HTML = `
<section class="imprint">
  <div class="imprint-content">
    <h2 class="imprint-title">Impresszum</h2>

    <p><strong>${escapeHtml(BOOK_TITLE)}</strong></p>
    <p>${escapeHtml(BOOK_AUTHOR)}</p>

    <p>
      © ${new Date().getFullYear()} ${escapeHtml(BOOK_AUTHOR)}<br />
      Minden jog fenntartva.
    </p>

    <p>
      A kötet versei a szerző szellemi tulajdonát képezik.<br />
      A mű részben vagy egészben történő utánközlése,<br />
      sokszorosítása vagy terjesztése csak a szerző<br />
      előzetes írásbeli engedélyével lehetséges.
    </p>

    <p class="imprint-meta">
      Magánkiadás<br />
      Magyarország
    </p>
  </div>
</section>
`;

// Precompute ids for chapters + poems for TOC links
const chapterMeta = chapters.map((ch) => {
  const chId = `ch-${makeUniqueId(ch.name)}`;
  const poemMeta = (ch.poems || []).map((p) => ({
    ...p,
    _id: `p-${makeUniqueId(p.title || "vers")}`,
  }));
  return { ...ch, _id: chId, poems: poemMeta };
});

// Chapter title page (full page, centered)
const chapterTitlePage = (ch) => `
<section class="chapter-title-page" id="${ch._id}">
  <div class="chapter-title">${escapeHtml(ch.name)}</div>
</section>
`;

// Poem block
const poemBlock = (p) => `
<section class="poem" id="${p._id}">
  <h2 class="poem-title">${escapeHtml(p.title)}</h2>
  <pre class="poem-text">${escapeHtml(p.poem)}</pre>
</section>
`;

// Build content in chapter order
const contentBlocks = chapterMeta
  .map((ch) => {
    const title = chapterTitlePage(ch);
    const poemsHtml = (ch.poems || []).map(poemBlock).join("\n");
    return `${title}\n${poemsHtml}`;
  })
  .join("\n");


const html = `<!DOCTYPE html>
<html lang="hu">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${escapeHtml(BOOK_TITLE)}</title>

  <link href="https://fonts.googleapis.com/css2?family=EB+Garamond:wght@400;500;600&display=swap" rel="stylesheet">

  <style>
    @page {
      size: A5;
      margin: 25mm 22mm 30mm 22mm;
    }
    @page:first { margin: 0; }

    body {
      font-family: "EB Garamond", serif;
      font-size: 12.5pt;
      line-height: 1.6;
      color: #111;
      margin: 0;
      padding: 0;
    }

    /* Cover */
    .cover {
      height: 100vh;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      text-align: center;
      page-break-after: always;
      box-sizing: border-box;
      padding: 25mm 22mm 30mm 22mm;
    }
    .cover-image {
      max-width: 70%;
      max-height: 45vh;
      object-fit: contain;
      display: block;
      margin: 0 auto 14mm auto;
    }
    .cover h1 {
      font-size: 42pt;
      font-weight: 600;
      margin: 0 0 8mm 0;
      letter-spacing: 0.04em;
    }
    .cover h2 {
      font-size: 18pt;
      font-weight: 400;
      margin: 0;
      letter-spacing: 0.02em;
    }

    /* Impresszum */
    section.imprint {
      page-break-after: always;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100%;
    }
    .imprint-content {
      text-align: center;
      font-size: 11.5pt;
      line-height: 1.6;
      max-width: 90%;
    }
    .imprint-title {
      font-weight: 500;
      letter-spacing: 0.06em;
      margin-bottom: 36px;
    }
    .imprint-content p { margin: 0 0 18px 0; }
    .imprint-meta { margin-top: 36px; font-size: 10.5pt; color: #444; }

    /* Chapter title page: full page, centered */
    .chapter-title-page {
      page-break-before: always;
      page-break-after: always;
      display: flex;
      align-items: center;
      justify-content: center;
      height: 100vh;
      text-align: center;
    }
    .chapter-title {
      font-size: 26pt;
      font-weight: 500;
      letter-spacing: 0.08em;
    }

    /* Poems */
    section.poem {
      page-break-before: always;
      page-break-inside: avoid;
    }
    h2.poem-title {
      text-align: center;
      font-weight: 500;
      margin-bottom: 24px;
      margin-top: 60px;
      letter-spacing: 0.04em;
    }
    pre.poem-text {
      white-space: pre-wrap;
      font-family: inherit;
      font-size: 12.5pt;
      margin: 0;
    }

    /* TOC (at the end) */
    section.toc {
      page-break-before: always;
      page-break-after: always;
    }
    .toc-title {
      text-align: center;
      font-weight: 500;
      letter-spacing: 0.06em;
      margin: 40px 0 28px 0;
    }
    .toc-chapter { margin: 0 0 14px 0; }
    .toc-chapter-row { margin: 0 0 6px 0; }
    .toc-poems { padding-left: 10mm; }
    .toc-poem-row { margin: 4px 0; }

    .toc-link {
      color: inherit;
      text-decoration: none;
    }
    .toc-chapter-link {
      font-weight: 500;
      letter-spacing: 0.02em;
    }
  </style>
</head>

<body>
  <section class="cover">
    <img src="${escapeHtml(COVER_IMG_URL)}" alt="Cover" class="cover-image" />
    <h1>${escapeHtml(BOOK_TITLE)}</h1>
    <h2>${escapeHtml(BOOK_AUTHOR)}</h2>
  </section>

  ${IMPRINT_HTML}

  ${contentBlocks}

</body>
</html>`;

return [{ json: { html } }];

// One OpenAI call for all poems: pack items into a single item
const poems = items.map((it, idx) => ({
  id: idx + 1,
  title: it.json.title ?? "",
  poem: it.json.poem ?? "",
  url: it.json.url ?? "",
}));

return [{
  json: {
    poems,
    bookTitle: "Versek",
    bookAuthor: "Kiszely Jószefné",
    coverImgUrl: "https://html.kiszely.work/assets/cover_pencil.jpg",
  }
}];

// poems + meta az Aggregate poems node-ból
const agg = $node["Aggregate poems1"].json;
// Get filtered poems from Wait node (user input)
const waitData = $node["Wait for poems1"].json;
const rawPoems = (waitData && (waitData.poems || waitData.body?.poems)) ? (waitData.poems || waitData.body?.poems) : (agg.poems || []);
const poems = rawPoems.map((p, i) => ({ ...p, id: i + 1 }));

// OpenAI response (jelen node inputja)
const content = $input.first().json.choices?.[0]?.message?.content ?? "{}";

let parsed;
try { parsed = JSON.parse(content); } catch { parsed = { categories: [] }; }

let categories = Array.isArray(parsed.categories) ? parsed.categories : [];

// validation
const n = poems.length;
const allIds = new Set();
for (const c of categories) {
  c.poem_ids = Array.isArray(c.poem_ids) ? c.poem_ids : [];
  for (const id of c.poem_ids) allIds.add(id);
}
const okCount = categories.length >= 4 && categories.length <= 8;
const okAll = allIds.size === n && [...allIds].every(id => id >= 1 && id <= n);

if (!okCount || !okAll) {
  const bucketCount = Math.min(4, Math.max(1, n));
  const names = ["Életképek", "Érzelmek", "Gondolatok", "Egyéb"];
  const buckets = Array.from({ length: bucketCount }, (_, i) => ({
    name: names[i] || `Fejezet ${i + 1}`,
    poem_ids: [],
  }));
  for (let i = 0; i < n; i++) buckets[i % bucketCount].poem_ids.push(i + 1);
  categories = buckets;
}

// chapters felépítése
const poemById = new Map(poems.map(p => [p.id, p]));
const chapters = categories.map(c => ({
  name: String(c.name || "").trim() || "Fejezet",
  poems: (c.poem_ids || []).map(id => poemById.get(id)).filter(Boolean),
}));

return [{
  json: {
    poems,
    chapters,
    bookTitle: agg.bookTitle,
    bookAuthor: agg.bookAuthor,
    coverImgUrl: agg.coverImgUrl,
  }
}];

parameters.jsonBody:
={{
  (() => {
    const rawPoems = $json.poems || $json.body?.poems || [];
    const poems = rawPoems.map((p, i) => ({ ...p, id: i + 1 }));

    const schemaHint = `
Return ONLY valid JSON in this exact shape:
{
  "categories": [
    {
      "name": "Kategória neve",
      "poem_ids": [1,2,3]
    }
  ]
}

Rules:
- categories count: 4..8
- every poem id 1..N appears exactly once across all poem_ids
- category names: Hungarian, short (1-3 words), book-like chapter titles
- try to balance categories (avoid 1 poem category unless necessary)
- try to come up with interesting chapter titles.
`;

    return JSON.stringify({
      model: $env.OPENAI_MODEL || "gpt-4.1-mini",
      temperature: 0.3,
      messages: [
        {
          role: "system",
          content:
            "You are a careful literary editor. Categorize poems into chapter themes for a Hungarian poetry book. Try to find interesting chaper names that fits to the poems in it."
        },
        {
          role: "user",
          content:
            schemaHint +
            "\n\nHere are the poems as JSON:\n" +
            JSON.stringify(poems)
        }
      ],
      response_format: { "type": "json_object" }
    });
  })()
}}

